INSERT INTO `products` (`id`, `name`, `code`, `slug`, `category_id`, `uom_id`, `brand_id`, `publication_id`, `product_type`, `barcode`, `file`, `thumbnail`, `short_description`, `description`, `profit`, `profit_percent`, `show_dashboard`, `serial`, `required_share`, `purchase_price`, `regular_price`, `sale_price`, `discount`, `discount_type`, `discount_start_date`, `discount_end_date`, `sku`, `meta_title`, `meta_description`, `meta_image`, `custom_barcode`, `favorite`, `trending`, `new_arrival`, `best_seller`, `status`, `created_by`, `updated_by`, `deleted_by`, `deleted_at`, `created_at`, `updated_at`) VALUES
(1, 'নীল কাফনে ঢাকা', 'COD202604011', 'neel-kafne-dhaka', 34, 1, 1, 24, 'book', 'asdsas', NULL, 'storage/media/product/2026-04-01-vGr9z4lEWmw4C7WHFyn7tI0SXoK1uXnZ7v3XoeKq.webp', '<p>হালিম খান ট্রয়</p>', '<p data-start=\"0\" data-end=\"45\">📘 <strong data-start=\"3\" data-end=\"43\">নীল কাফনে ঢাকা — বই (হালিম খান ট্রয়)</strong></p><p data-start=\"47\" data-end=\"223\"><strong data-start=\"47\" data-end=\"67\">“নীল কাফনে ঢাকা”</strong> হলো <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\">হালিম খান ট্রয়</span> রচিত একটি সমকালীন বাংলা উপন্যাস, যেখানে রহস্য, বাস্তবতা ও মানবিক আবেগ একসাথে মিশে একটি গভীর গল্প নির্মাণ করেছে।</p><hr data-start=\"225\" data-end=\"228\"><p data-start=\"230\" data-end=\"295\">✍️ <strong data-start=\"233\" data-end=\"250\">লেখক সম্পর্কে</strong><br data-start=\"250\" data-end=\"253\">\r\n📌 <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\">হালিম খান ট্রয়</span></p><p data-start=\"297\" data-end=\"466\">তিনি সমকালীন বাংলা সাহিত্যের একজন উদীয়মান লেখক। তার লেখায় সাধারণত রহস্য, থ্রিলার ও সামাজিক বাস্তবতার মিশ্রণ দেখা যায়। সহজ ভাষা ও কাহিনির গতি তার লেখার বিশেষ বৈশিষ্ট্য।</p><hr data-start=\"468\" data-end=\"471\"><p data-start=\"473\" data-end=\"737\">📖 <strong data-start=\"476\" data-end=\"497\">বইয়ের প্রধান তথ্য</strong><br data-start=\"497\" data-end=\"500\">\r\nনাম: নীল কাফনে ঢাকা<br data-start=\"519\" data-end=\"522\">\r\nলেখক: হালিম খান ট্রয়<br data-start=\"542\" data-end=\"545\">\r\nভাষা: বাংলা<br data-start=\"556\" data-end=\"559\">\r\nধরণ: রহস্য / থ্রিলার / সামাজিক উপন্যাস<br data-start=\"696\" data-end=\"699\">\r\nপৃষ্ঠা সংখ্যা: মাঝারি আকারের উপন্যাস</p><hr data-start=\"739\" data-end=\"742\"><p data-start=\"744\" data-end=\"782\">📌 <strong data-start=\"747\" data-end=\"780\">বইটির মূল বক্তব্য ও বিষয়বস্তু</strong></p><p data-start=\"784\" data-end=\"892\">“নীল কাফনে ঢাকা” একটি রহস্যঘেরা গল্প, যেখানে মৃত্যু, অজানা সত্য এবং মানবিক দ্বন্দ্ব ধীরে ধীরে উন্মোচিত হয়।</p><p data-start=\"894\" data-end=\"997\">🔹 গল্পে একটি অস্বাভাবিক ঘটনার সূত্র ধরে কাহিনি এগোতে থাকে, যা ধীরে ধীরে বড় এক রহস্যের দিকে নিয়ে যায়।</p><p data-start=\"999\" data-end=\"1065\">🔹 “নীল কাফন” এখানে প্রতীক—লুকানো সত্য, বেদনা ও অপ্রকাশিত ঘটনার।</p><p data-start=\"1067\" data-end=\"1159\">🔹 চরিত্রগুলোর ভেতরের ভয়, অপরাধবোধ ও বাস্তবতার মুখোমুখি হওয়ার সংগ্রাম গল্পটিকে গভীরতা দেয়।</p><hr data-start=\"1161\" data-end=\"1164\"><p data-start=\"1166\" data-end=\"1202\">📍 <strong data-start=\"1169\" data-end=\"1200\">বইটি কেন পড়া গুরুত্বপূর্ণ?</strong></p><p data-start=\"1204\" data-end=\"1384\">📌 রহস্য ও থ্রিলারধর্মী কাহিনি পছন্দ করলে এটি আকর্ষণীয়।<br data-start=\"1259\" data-end=\"1262\">\r\n📌 মানবিক আবেগ ও মনস্তাত্ত্বিক দিকগুলো সুন্দরভাবে উপস্থাপিত।<br data-start=\"1322\" data-end=\"1325\">\r\n📌 ধীরে ধীরে রহস্য উন্মোচনের কারণে পাঠকের আগ্রহ ধরে রাখে।</p><hr data-start=\"1386\" data-end=\"1389\"><p data-start=\"1391\" data-end=\"1407\">✨ <strong data-start=\"1393\" data-end=\"1405\">সংক্ষেপে</strong></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p data-start=\"1409\" data-end=\"1588\">“নীল কাফনে ঢাকা” একটি রহস্যময় ও আবেগঘন উপন্যাস, যেখানে অজানা সত্য, মৃত্যু ও মানুষের অন্তর্দ্বন্দ্ব একসাথে মিলিত হয়ে একটি টানটান কাহিনি তৈরি করেছে—যা পাঠককে শেষ পর্যন্ত ধরে রাখে।</p>', 10000, 0, 1, NULL, 10, 170.00, 190.00, 190.00, 0.00, 'amount', '2026-01-20', '2026-02-21', 'SKUS', 'meta', 'cssdsfsf', 'storage/media/product/2026-01-20-FLxMajI5xjcg9zj2q2IBLQh6RqZUGujs5DiDmI6I.webp', 1, 1, 0, 0, 0, 1, 1, 1, NULL, NULL, '2026-01-20 04:15:44', '2026-04-05 04:28:53'),
(2, 'কোথায় আলো', 'COD202603292', 'kothay-alo', 32, 1, 1, 24, 'book', 'sdasd', NULL, 'storage/media/product/2026-03-29-XeMBthNbKfn1r0GxKOzo3FDA33Dq0smU5zniPK8w.webp', '<p> সুনীল গঙ্গোপাধ্যায়</p>', '<p>কোথায় আলো</p><p>লেখকঃ সুনীল গঙ্গোপাধ্যায়</p><p>ভাষাঃ বাংলা</p><p>সংকলন ও রচনাঃ হুমায়ূন আহমেদ । </p><p>📘 বইয়ের নাম</p><p>কোথায় আলো</p><p>🏷️ ক্যাটাগরি</p><p>উপন্যাস </p><p>🌐 ভাষা</p><p>বাংলা</p><p>📖 বইয়ের সংক্ষিপ্ত বিবরণ</p><p> উপন্যাসটি জীবনের বিভিন্ন দিক, সম্পর্ক এবং মানবিক মূল্যবোধ নিয়ে আলোচনা করে। এটি সুনীল গঙ্গোপাধ্যায়ের অন্যতম শ্রেষ্ঠ রচনা, যেখানে তিনি মানুষের জীবনের জটিলতা এবং সৌন্দর্য তুলে ধরেছেন। </p><p>⭐ বইয়ের মূল বিষয়বস্তু</p><p> জীবনের অর্থ খোঁজা, সম্পর্কের জটিলতা, এবং মানবিক মূল্যবোধের অনুসন্ধান। সুনীল গঙ্গোপাধ্যায় এখানে মানুষের জীবনের বিভিন্ন দিক তুলে ধরেছেন। </p><p>🎯 কেন বইটি পড়বেন</p><p> সুনীল গঙ্গোপাধ্যায়ের অসাধারণ লেখনীর সাথে জীবনের গভীরতা খুঁজে পাওয়া, এবং মানুষের সম্পর্ক ও মূল্যবোধ সম্পর্কে নতুন করে ভাবা। </p><p>📚 কার জন্য উপযুক্ত</p><p>যারা সুনীল গঙ্গোপাধ্যায়ের লেখনী পছন্দ করেন, জীবনের গভীরতা খুঁজতে চান, এবং বাংলা সাহিত্যের ভক্ত, তাদের জন্য উপযুক্ত। </p><p><br></p>', 10000, 0, 1, NULL, 1, 275.00, 275.00, 275.00, 0.00, 'amount', '2026-01-20', '2026-02-26', 'ssds', 'sdsadad', 'sadasdasd', 'storage/media/product/2026-01-20-NPtdHB2jK5Qnb7ZQHRfq1tlCqh3GLhOoYfA8dHbZ.webp', 1, 1, 0, 0, 0, 1, 1, 1, NULL, NULL, '2026-01-20 04:26:34', '2026-04-05 04:27:20'),
(3, 'সমুদ্র থেকে সমতলে', 'COD202603083', 'smudr-theke-smtle', 32, 1, 1, 24, 'book', 'sdfsd', NULL, 'storage/media/product/2026-03-29-RxwQzkLKFnsVUGs0Z7JZESv8YNFkFHn5ySYDr2zC.webp', '<p>সোলায়মান হোসাইন </p>', '<p><b><span style=\"font-size: 18px;\">সমুদ্র থেকে সমতলে </span> </b></p><p>লেখকঃ সোলায়মান হোসাইন </p><p>ভাষাঃ বাংলা</p><p>সংকলন ও রচনাঃ অধ্যায়ন প্রকাশন । </p><p><b><br></b></p><p><b><span style=\"font-size: 18px;\">📘 বইয়ের নাম</span></b></p><p>সমুদ্র থেকে সমতলে</p><p><br></p><p><b><span style=\"font-size: 18px;\">🏷️ ক্যাটাগরি</span></b></p><p>অনুপ্রেরণামূলক ও আত্ম-উন্নয়নমূলক। </p><p><br></p><p><b><span style=\"font-size: 18px;\">🌐 ভাষা</span></b></p><p>বাংলা</p><p><br></p><p>📖 বইয়ের সংক্ষিপ্ত বিবরণ</p><p>সমুদ্র থেকে সমতলে বইটি সোলায়মান সুখনের জীবনের অভিজ্ঞতা ও সংগ্রামের গল্প, যা পাঠকদের অনুপ্রাণিত করে এবং জীবনের চ্যালেঞ্জ মোকাবিলায় সাহায্য করে।</p><p><br></p><p>⭐ বইয়ের মূল বিষয়বস্তু</p><p>সমুদ্র থেকে সমতলে বইটি সোলায়মান সুখনের জীবনের অভিজ্ঞতা ও সংগ্রামের গল্প, যা পাঠকদের অনুপ্রাণিত করে এবং জীবনের চ্যালেঞ্জ মোকাবিলায় সাহায্য করে।</p><p><br></p><p>🎯 কেন বইটি পড়বেন</p><p>সোলায়মান সুখনের জীবনের অভিজ্ঞতা ও সংগ্রামের গল্প থেকে শিক্ষা নেওয়া, নিজের জীবনের চ্যালেঞ্জ মোকাবিলায় অনুপ্রাণিত হওয়া, এবং নিজেকে গড়ে তোলার জন্য প্রেরণা পাওয়া। </p><p>📚 কার জন্য উপযুক্ত</p><p>যারা জীবনের চ্যালেঞ্জ মোকাবিলায় অনুপ্রেরণা খুঁজছেন, নিজেকে গড়ে তুলতে চান, এবং সফলতার পথে এগিয়ে যেতে চান। </p><p><br></p>', 10000, 0, 1, NULL, 1, 200.00, 200.00, 200.00, 0.00, 'amount', NULL, NULL, 'BK-018', 'sdfsddf', 'sdfsd', 'storage/media/product/2026-03-29-RxwQzkLKFnsVUGs0Z7JZESv8YNFkFHn5ySYDr2zC.webp', 1, 1, 0, 0, 0, 1, 1, 1, NULL, NULL, '2026-01-22 04:46:01', '2026-04-05 04:25:08'),
